    alertGet: typeof window._aioGetAlerts === 'function',
    alertAdd: typeof window._aioAddAlert === 'function',
    alertParse: typeof window._aioParseAlertIntent === 'function',
    alertCheck: typeof window._aioCheckAlerts === 'function',
