      var source = hasExistingUsableLineage ? (existingLabel || existingKind) : (isCanvas ? 'chart-render' : (isRuleSink ? 'AIO_RULESET' : (isSnapshotSink ? 'DATA_SNAPSHOT' : (ds.source || ld.source || 'unavailable'))));
