  lockoutRally: { date: '2025.04.25', zbt: 0.617, context: '2025년 4월 Lock-out Rally ZBT 0.38→0.617 정식 돌파' },
  bullCaseNarrowBreadth: ['2019', '2024'],
  lastUpdated: '2026-04-18'
