      '^KS11': { price: S.kospi, pct: S.kospiPct },
      '^KQ11': { price: S.kosdaq, pct: S.kosdaqPct },
      // v34.5: GMO 테이블 누락 심볼 fallback
      '^TNX': { price: 4.31, pct: +0.54 },
